/**
 * Helm tab logic: no DOM, so it runs under node for tests/test_helm.mjs. docs/helm.md
 *
 * Raw NMEA (store.state) -> the same correction chain as tools/build_polar.py's calibrate()
 * (helm_chain() there; a parity fixture holds the two together, P20) -> Typon's ORC targets ->
 * one steering instruction. Calibration constants come from helm-targets.js, generated by
 * `build_polar.py --write-js` and frozen for the race.
 *
 * Numbers are all CORRECTED: the helm steers by this display, not the B&G, whose raw readings carry
 * the vane offset, upwash, heel and paddlewheel errors.
 */
const HelmLogic = (() => {
    let H = (typeof HELM_TARGETS !== 'undefined') ? HELM_TARGETS : null;

    // Rules and timing. Named here so they can be tuned after a race in one place.
    const C = {
        FLOOR: 0.3,          // kn under target: past this, speed is the problem (docs/polar.md §3)
        GROOVE_UP: 1.5,      // deg wide of target upwind before "point higher"
        HOT_DOWN: 2,         // deg hot of target downwind before "sail deeper"
        TACK_S: 60,          // s after a tack/rounding when footing to accelerate is right
        TACK_HOLD_S: 10,     // s the wind must stay on the new side to count as a tack
        SMOOTH_S: 5,         // s average for AWA, speed, wind
        VMG_S: 15,           // s average for VMG %, which jumps with waves and puffs
        HOLD_S: 3,           // s a new instruction must persist before the banner changes
        // s without a reading before that input counts as missing. Set from the measured sentence
        // rates in the BBS logs: apparent wind ($IIMWV,R) every ~4.7 s (max 5.2), boat speed ($IIVHW)
        // every ~2.2 s (max 2.6), heel ($YXXDR) at 20 Hz. A single 5 s limit flickered NO WIND.
        STALE_WIND_S: 12,
        STALE_SPEED_S: 8,
        STALE_S: 5,          // heel, and "nothing at all" (heel's silence is the first sign of a dead feed)
        MIN_TWS: 4,          // kn: below the certificate's first column there are no targets
        MODE_DOWN: 100,      // TWA over which upwind switches to downwind...
        MODE_UP: 80,         // ...and under which it switches back (hysteresis)
        SAMPLE_MS: 200,      // one smoothing sample per this much stream time
        REACH_IN: 25,        // deg of TWA from the target angle: past this we are reaching, not beating/running...
        REACH_OUT: 20,       // ...and back under this we are sailing to the target again (hysteresis)
        DIAL_DOWN_AWA: 55,   // deg corrected AWA: reaching, the dial takes the 60-180 scale above this...
        DIAL_UP_AWA: 50,     // ...and the 0-45 one back under this (the upwind scale ends at 45)
    };

    const rad = d => d * Math.PI / 180, deg = r => r * 180 / Math.PI;
    const clip = (x, lo, hi) => Math.min(Math.max(x, lo), hi);
    const signed = a => ((((a + 180) % 360) + 360) % 360) - 180;
    function interp(x, xs, ys) {                       // np.interp: clamps at both ends
        if (x <= xs[0]) return ys[0];
        if (x >= xs[xs.length - 1]) return ys[ys.length - 1];
        let j = 1;
        while (xs[j] < x) j++;
        return ys[j - 1] + (ys[j] - ys[j - 1]) * (x - xs[j - 1]) / (xs[j] - xs[j - 1]);
    }

    // ---- the correction chain, mirroring build_polar.py function by function
    function paddleStarboard(bsp, roll) {
        const c = H.cal, heel = roll == null || Number.isNaN(roll) ? 0 : roll;
        const w = clip((-heel - c.paddleHeel[0]) / (c.paddleHeel[1] - c.paddleHeel[0]), 0, 1);
        return bsp - w * (1 - c.paddleSlope) * (bsp - c.paddlePivot);
    }
    function heelCorrect(awa, aws, roll) {
        const h = rad(Math.abs(roll)), a = rad(signed(awa));
        const x = aws * Math.cos(a), y = aws * Math.sin(a) / Math.cos(h);
        return [(((deg(Math.atan2(y, x))) % 360) + 360) % 360, Math.hypot(x, y)];
    }
    function leeway(roll, stw, awa) {
        const c = H.cal, [A, B, n] = c.leeK, h = Math.abs(roll);
        const taper = clip((90 - Math.abs(signed(awa))) / 60, 0, 1);
        return clip((A * Math.min(h / c.leeRampHeel, 1) + B * Math.pow(h / c.leeRefHeel, n))
            * Math.pow(c.leeRefStw / Math.max(stw, 3.0), 2), 0, c.leeMax) * taper;
    }
    function trueWind(awa, aws, stw, off, sym, lee) {
        const s = signed(awa), taper = clip((90 - Math.abs(s)) / 60, 0, 1);
        const a = rad(s - off - sym * taper * Math.sign(s)), L = rad(lee) * Math.sign(s);
        const x = aws * Math.sin(a) + stw * Math.sin(L), y = aws * Math.cos(a) - stw * Math.cos(L);
        return [deg(Math.atan2(x, y)) + deg(L), Math.hypot(x, y)];
    }
    function upwashAt(tws10) {
        const c = H.cal;
        return clip(c.upwashSym + c.upwashSlope * (tws10 - c.upwashRefTws), c.upwashMin, c.upwashMax);
    }
    /** Raw readings -> corrected. roll signed (negative = heeled to port). */
    function chain(awa, aws, bsp, roll, k = H.cal.paddleK) {
        const c = H.cal;
        const stw = paddleStarboard(bsp, roll) * k;
        const [awaH, awsH] = heelCorrect(awa, aws, roll);
        const lee = leeway(roll, stw, awaH);
        const [, t1] = trueWind(awaH, awsH, stw, c.constOffset, c.constSym, lee);
        const up = upwashAt(t1 * c.twsTo10m);
        const [twa, tws] = trueWind(awaH, awsH, stw, c.offset, up, lee);
        const s = signed(awaH), taper = clip((90 - Math.abs(s)) / 60, 0, 1);
        return { stw, awaCorr: s - c.offset - up * taper * Math.sign(s), twa: signed(twa), tws10: tws * c.twsTo10m, lee };
    }
    /** ORC's TWA (through the water) -> corrected apparent angle by the bow, at the speed actually sailed. */
    function awaByBow(twa, tws10, stw, lee) {
        const tm = tws10 / H.cal.twsTo10m, t = rad(twa);
        return deg(Math.atan2(tm * Math.sin(t), tm * Math.cos(t) + stw)) - lee;
    }
    /** ORC target at this 10 m wind: TWA, boat speed, VMG. */
    function targets(tws10, up) {
        const o = H.orc;
        if (up) {
            const twa = interp(tws10, o.tws, o.beatAngle), vmg = interp(tws10, o.tws, o.beatVmg);
            return { twa, vmg, speed: vmg / Math.cos(rad(twa)) };
        }
        const twa = interp(tws10, o.tws, o.gybeAngle), vmg = interp(tws10, o.tws, o.runVmg);
        return { twa, vmg, speed: vmg / -Math.cos(rad(twa)) };
    }

    /** ORC rated speed at any TWA: bilinear on the router's table, clamped (polar_speed() in Python). */
    function polarSpeed(twa, tws10) {
        const P = H.orc.polar, a = clip(Math.abs(twa), P.twa[0], P.twa[P.twa.length - 1]);
        const col = P.tws.map((_, j) => interp(a, P.twa, P.bsp.map(row => row[j])));
        return interp(tws10, P.tws, col);
    }

    // ---- the instruction. Upwind: speed first, never foot below the target angle when slow.
    // Downwind: slow only matters if VMG suffers too. docs/helm.md has the table and the evidence.
    function decide({ up, reach, dA, dS, vmgPct, sinceTack }) {
        // reaching: the mark sets the course, so no angle advice; speed against the polar at this angle
        if (reach) return { key: dS < -C.FLOOR ? 'reach-slow' : 'reach', main: 'REACH', kind: dS < -C.FLOOR ? 'build' : 'groove', steer: 0 };
        if (up) {
            if (dS < -C.FLOOR) {
                if (sinceTack < C.TACK_S) return { key: 'bearoff-accel', main: 'BEAR OFF', kind: 'build', steer: 1 };
                if (dA < -C.GROOVE_UP) return { key: 'bearoff-pinch', main: 'BEAR OFF', kind: 'build', steer: 1 };
                return { key: 'build', main: 'BUILD SPEED', kind: 'build', steer: 0 };
            }
            if (dS >= 0 && dA > C.GROOVE_UP) return { key: 'higher', main: 'POINT HIGHER', kind: 'spend', steer: -1 };
            // high but not slow: hold it only while it pays. polar.md §3 measured 2-4 deg high gaining,
            // nothing past that, and speed can bleed off slower than the floor catches it.
            if (dA < -C.GROOVE_UP && vmgPct < 100) return { key: 'bearoff-high', main: 'BEAR OFF', kind: 'spend', steer: 1 };
            return { key: 'groove', main: 'IN THE GROOVE', kind: 'groove', steer: 0 };
        }
        if (dS < -C.FLOOR && vmgPct < 100) return { key: 'heat', main: 'HEAT UP', kind: 'build', steer: -1 };
        if (dS >= 0 && dA < -C.HOT_DOWN) return { key: 'deeper', main: 'SAIL DEEPER', kind: 'spend', steer: 1 };
        return { key: 'groove', main: 'IN THE GROOVE', kind: 'groove', steer: 0 };
    }
    /** Banner text with its arrow. Upwind ▲ head up / ▼ bear away. Downwind the way to turn the bow,
     *  which is also the way the bar moves on the dial (stbd gybe: deeper = turn to port = ◀). */
    function label(main, steer, up, side) {
        if (!steer) return main;
        if (up) return (steer < 0 ? '▲ ' : '▼ ') + main;
        return side * -steer < 0 ? '◀ ' + main : main + ' ▶';
    }

    // ---- smoothing over stream time
    function mean(xs) { return xs.reduce((a, b) => a + b, 0) / xs.length; }
    function circMean(xs) {
        const s = mean(xs.map(a => Math.sin(rad(a)))), c = mean(xs.map(a => Math.cos(rad(a))));
        return deg(Math.atan2(s, c));
    }

    /** Which dial scale to draw, 'up' (AWA 0-45) or 'down' (60-180). Beating or running it is the
     *  mode. Reaching there is no target to show, only where we are, and a close reach in upwind mode
     *  (AWA 50-70) sat pinned past the end of the 0-45 scale, so the scale follows the AWA. */
    function dialScale(prev, vm) {
        if (!vm.ok) return prev || 'up';
        if (!vm.reach) return vm.mode;
        if (vm.awa > C.DIAL_DOWN_AWA) return 'down';
        if (vm.awa < C.DIAL_UP_AWA) return 'up';
        return prev || vm.mode;
    }

    /** The live engine: feed it the store's state and the current time, get the view model back. */
    function create() {
        let buf = [], lastT = null, mode = null, side = 0, flipSide = 0, flipSince = null;
        let lastTackT = -Infinity, shown = null, cand = null, candSince = null, reach = false;
        let reachCand = null, reachSince = null;

        function reset() {
            buf = []; lastT = null; mode = null; side = 0; flipSide = 0; flipSince = null;
            lastTackT = -Infinity; shown = null; cand = null; candSince = null; reach = false;
            reachCand = null; reachSince = null;
        }
        function noData(main, sub) {
            shown = null; cand = null; candSince = null;
            return { ok: false, main, sub, kind: 'nodata' };
        }

        /** st = store.state; now = ms of the stream clock (wall time live, log time in replay). */
        function update(st, now) {
            const age = at => (at == null ? Infinity : (now - at) / 1000);
            const aW = age(st.awaAt), aB = age(st.bspAt), aR = age(st.rollAt);
            if (aW === Infinity && aB === Infinity && aR === Infinity) return noData('NO NMEA', 'no instrument data');
            if (Math.min(aW, aB, aR) > C.STALE_S) return noData('NO NMEA', `nothing for ${Math.round(Math.min(aW, aB, aR))} s`);
            if (aW > C.STALE_WIND_S || st.awa == null || st.aws == null) return noData('NO WIND', aW === Infinity ? 'no wind reading' : `wind ${Math.round(aW)} s old`);
            if (aB > C.STALE_SPEED_S || st.bsp == null) return noData('NO SPEED', aB === Infinity ? 'no boat speed' : `speed ${Math.round(aB)} s old`);
            if (aR > C.STALE_S || st.roll == null) return noData('NO HEEL', 'heel needed to correct wind and leeway');

            const t = Math.max(st.awaAt, st.bspAt, st.rollAt);
            if (lastT !== null && (t < lastT || t - lastT > 30000)) reset();   // replay seek or a gap
            const c = chain(st.awa, st.aws, st.bsp, st.roll);
            const sample = { t, ...c };
            if (buf.length && t - buf[buf.length - 1].t < C.SAMPLE_MS) buf[buf.length - 1] = sample;
            else buf.push(sample);
            lastT = t;
            buf = buf.filter(s => t - s.t <= C.VMG_S * 1000);
            const recent = buf.filter(s => t - s.t <= C.SMOOTH_S * 1000);
            const awaCorr = circMean(recent.map(s => s.awaCorr)), twa = circMean(recent.map(s => s.twa));
            const stw = mean(recent.map(s => s.stw)), tws10 = mean(recent.map(s => s.tws10)), lee = mean(recent.map(s => s.lee));

            if (tws10 < C.MIN_TWS) return noData('TOO LIGHT', `${tws10.toFixed(1)} kn wind, under the ORC range`);

            // mode with hysteresis; a mode change counts as a rounding
            const aTwa = Math.abs(twa);
            const newMode = mode === null ? (aTwa < 90 ? 'up' : 'down')
                : mode === 'up' && aTwa > C.MODE_DOWN ? 'down' : mode === 'down' && aTwa < C.MODE_UP ? 'up' : mode;
            // a switch redraws the whole dial, so the banner goes with it rather than 3 s later
            let switched = mode !== null && newMode !== mode;
            if (switched) lastTackT = t;
            mode = newMode;
            const up = mode === 'up';

            // tack / gybe: the wind stays on the other side for TACK_HOLD_S; the window runs from the flip
            const s = Math.sign(awaCorr) || side || 1;
            if (side === 0) side = s;
            else if (s !== side) {
                if (flipSide !== s) { flipSide = s; flipSince = t; }
                if (t - flipSince >= C.TACK_HOLD_S * 1000) { side = s; lastTackT = flipSince; flipSide = 0; }
            } else flipSide = 0;

            const tg = targets(tws10, up);
            // reaching: TWA far from the target angle (hysteresis), held HOLD_S like the banner, since it
            // takes the target off the dial and puts it back; entering or leaving counts as a rounding
            const off = Math.abs(aTwa - tg.twa);
            const nowReach = reach ? off > C.REACH_OUT : off > C.REACH_IN;
            if (nowReach === reach) reachCand = null;
            else if (!shown || buf.length < 2) reach = nowReach;   // a fresh start shows what it sees
            else {
                if (reachCand !== nowReach) { reachCand = nowReach; reachSince = t; }
                if (t - reachSince >= C.HOLD_S * 1000) {
                    reach = nowReach; reachCand = null; lastTackT = reachSince; switched = true;
                }
            }
            const tSpeed = reach ? polarSpeed(aTwa, tws10) : tg.speed;
            const tAwa = reach ? null : awaByBow(tg.twa, tws10, stw, lee);
            const awa = Math.abs(awaCorr), dA = reach ? 0 : awa - tAwa, dS = stw - tSpeed;
            const vmgs = buf.map(b => {
                const g = targets(b.tws10, up);
                return 100 * b.stw * Math.cos(rad(Math.abs(b.twa))) * (up ? 1 : -1) / g.vmg;
            });
            const vmgPct = mean(vmgs);
            const sinceTack = (t - lastTackT) / 1000;

            const d = decide({ up, reach, dA, dS, vmgPct, tws10, sinceTack });
            // banner hold: a new instruction must persist before it replaces the shown one
            if (!shown || switched) { shown = d; cand = null; }
            else if (d.key !== shown.key) {
                if (!cand || cand.key !== d.key) { cand = d; candSince = t; }
                if (t - candSince >= C.HOLD_S * 1000) { shown = d; cand = null; }
            } else { shown = d; cand = null; }

            return {
                ok: true, mode, up, side,
                main: label(shown.main, shown.steer, up, side), sub: '',   // the banner is the instruction alone; the numbers are on the dial
                kind: shown.kind, key: shown.key, reach,
                awa, tAwa, dA, stw, tSpeed, floor: tSpeed - C.FLOOR, dS, polarPct: 100 * stw / tSpeed,
                tws10, twa: aTwa, vmgPct, sinceTack, aboveRange: tws10 > H.orc.tws[H.orc.tws.length - 1],
            };
        }
        return { update, reset };
    }

    return {
        C, signed, interp, paddleStarboard, heelCorrect, leeway, trueWind, upwashAt, chain, awaByBow, targets, polarSpeed,
        decide, label, dialScale, create, setTargets: t => { H = t; },
    };
})();

if (typeof module !== 'undefined') module.exports = HelmLogic;
